const { from, to, subject, textBody, htmlBody, cc, bcc, replyTo, tag, trackOpens, trackLinks } = $.input;
if (!from || !to || !subject) throw new Error('from, to, and subject are required');
if (!textBody && !htmlBody) throw new Error('At least one of textBody or htmlBody is required');

const body = { From: from, To: to, Subject: subject };
if (textBody) body.TextBody = textBody;
if (htmlBody) body.HtmlBody = htmlBody;
if (cc) body.Cc = cc;
if (bcc) body.Bcc = bcc;
if (replyTo) body.ReplyTo = replyTo;
if (tag) body.Tag = tag;
if (trackOpens) body.TrackOpens = true;
if (trackLinks) body.TrackLinks = trackLinks;

return { body };

const resp = $.steps.sendEmail.response || {};
return {
  messageId: resp.MessageID || '',
  to: resp.To || $.input.to,
  submittedAt: resp.SubmittedAt || '',
  errorCode: resp.ErrorCode || 0,
  message: resp.Message || '',
  sent: resp.ErrorCode === 0 && !!resp.MessageID,
  summary: resp.MessageID ? `Sent "${$.input.subject}" to ${$.input.to} via Postmark` : `Failed: ${resp.Message || 'Unknown error'}`
};
